import { Table, IntegerColumn, StringColumn, TableNameColumn } from '../../db'

export const sys_number = Table({
    name: 'sys_number',
    schema: {
        category: TableNameColumn({ mandatory: false }),
        maximum_digits: IntegerColumn({ label: 'Number of Digits', default: 7 }),
        number: IntegerColumn({ default: 1000 }),
        prefix: StringColumn({}),
    },
})
